insert into public.tfi_master_data_rows (
  category_key,source_row_number,row_kind,source_values,current_values,
  source_notes,source_fingerprint,record_status,row_editable,version
)
select
  'product_standard',
  source_row_number,
  row_kind,
  row_values,
  row_values,
  '[]'::jsonb,
  encode(extensions.digest(convert_to(row_values::text,'UTF8'),'sha256'),'hex'),
  'active',
  row_kind='data',
  1
from source_rows
on conflict (category_key,source_row_number) do nothing;

update public.tfi_master_data_categories
set
  source_range='A1:U200',
  source_row_count=200,
  reference_count=100,
  source_count_note='100 product variants across 43 selectable product groups; 44 family-header rows including one ungrouped placeholder; 43 reserved new-variant slots; 12 helper/default-shift rows. Columns F, G and S are formula/read-only.'
where category_key='product_standard';

do $verify$
declare
  v_total integer;
  v_data integer;
  v_groups integer;
  v_reserved integer;
  v_helpers integer;
begin
  select count(*) into v_total
  from public.tfi_master_data_rows
  where category_key='product_standard' and record_status='active';

  select count(*) into v_data
  from public.tfi_master_data_rows
  where category_key='product_standard' and record_status='active' and row_kind='data';

  select count(*) into v_groups
  from public.tfi_master_data_rows
  where category_key='product_standard' and record_status='active' and row_kind='group_header';

  select count(*) into v_reserved
  from public.tfi_master_data_rows
  where category_key='product_standard' and record_status='active' and row_kind='reserved_slot';

  select count(*) into v_helpers
  from public.tfi_master_data_rows
  where category_key='product_standard' and record_status='active' and row_kind='helper';

  if v_total <> 200 or v_data <> 100 or v_groups <> 44 or v_reserved <> 43 or v_helpers <> 12 then
    raise exception 'Product Standard expansion verification failed: total %, data %, groups %, reserved %, helpers %.',
      v_total,v_data,v_groups,v_reserved,v_helpers;
  end if;
end;
$verify$;

commit;
